import {lifePages,lifeMeanings,lifeCases} from './life-stages-content.mjs';
import {lifeView,startLife,resumeLife,setLifePage,setLifeView,chooseLifeNeighbor,chooseLifeMeaning,addLifeSupport,checkLife,lifeCheckMatches} from './life-stages-core.mjs';
import {lifeStageDiagram} from './life-stages-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const stage=(source,id)=>source.stages.find(s=>s.id===id);
const stageLabel=(source,id)=>id===null?'No stage chosen':id==='unsure'?'Not sure yet':stage(source,id)?.label||id;
const meaningLabel=id=>lifeMeanings.find(x=>x.id===id)?.label||'No meaning chosen';
const recordedMatch=value=>value===null?'not assessed':value?'fits':'does not fit';
function proposed(source,input){if(!input.neighbor||input.neighbor==='unsure')return '<section class="life-proposed"><h3>Our proposed forward link</h3><p>No pair chosen yet. A stage choice will appear here; no answer has been supplied.</p></section>';const from=source.direction==='before'?input.neighbor:source.reference,to=source.direction==='before'?source.reference:input.neighbor,generation=from==='adult'&&to==='egg';return `<section class="life-proposed" data-life-from="${from}" data-life-to="${to}" data-life-generation="${generation}"><h3>Our proposed forward link</h3><div class="life-forward-pair"><div>${lifeStageDiagram(stage(source,from))}<strong>${esc(stageLabel(source,from))}</strong></div><div class="life-link${generation?' life-offspring-link':''}"><span class="life-link-direction">Leads forward to</span><span class="life-arrow" aria-hidden="true">→</span>${generation?'<strong>offspring</strong><small>another generation</small>':''}</div><div>${lifeStageDiagram(stage(source,to))}<strong>${esc(stageLabel(source,to))}</strong></div></div><p class="tiny">This is our proposed pair, not a confirmed life-stage relationship.${source.direction==='before'?' Looking back through a chart does not mean an animal develops backward.':''}</p>${generation?'<p>An adult female can lay eggs that begin offspring. The adult does not turn into its own egg.</p>':''}</section>`;}
function fullSource(source){return `<details class="life-frozen-source"><summary>Pictures and facts kept with this task</summary><p><strong>${esc(source.commonName)}</strong> · <i>${esc(source.species)}</i></p><p>${esc(source.overview)}</p><div class="life-source-stages">${source.stages.map(s=>`<section><h4>${esc(s.label)}</h4>${lifeStageDiagram(s)}<p>${esc(s.text)}</p></section>`).join('')}</div><ul>${source.links.map(link=>`<li><strong>${esc(stageLabel(source,link.from))} → ${esc(stageLabel(source,link.to))}${link.meaning==='offspring'?' · offspring, another generation':''}:</strong> ${esc(link.text)}</li>`).join('')}</ul></details>`;}
function inspect(r){const selected=stage(r.source,r.view);return `<h2 id="life-prompt" tabindex="-1">One butterfly, changing bodies</h2><div class="life-inspect-layout"><section>${lifeStageDiagram(selected)}</section><section><h3>${esc(selected.label)}</h3><p>${esc(selected.text)}</p>${hearButton(selected.text,'Hear this stage')}<div class="life-view-choices" role="group" aria-label="Choose an inspection picture">${r.source.stages.map(s=>button(`data-life-view="${s.id}" aria-pressed="${r.view===s.id}"`,s.label,r.view===s.id)).join('')}</div>${button('data-life-page="connect"','Connect two stages',true)}</section></div><p class="tiny">Original teaching pictures of a possible successful life story. Their sizes are chosen for clarity; they do not track a real animal.</p>`;}
function connect(r){const reference=stage(r.source,r.source.reference);return `<h2 id="life-prompt" tabindex="-1">${esc(r.source.question)}</h2><div class="life-connect-layout"><section class="life-reference"><h3>Reference: ${esc(reference.label)}</h3>${lifeStageDiagram(reference)}${hearButton(r.source.question+' '+reference.text,'Hear this question and reference')}<details id="life-reference-text" data-round="${r.id}"><summary>Read or hear this reference stage</summary><p>${esc(reference.text)}</p>${hearButton(reference.text,'Hear the reference stage')}</details></section><section class="life-neighbor"><h3>Choose a chart neighbor</h3><div class="life-picture-choices" role="group" aria-label="Choose the neighboring stage">${r.source.options.map(id=>{const s=stage(r.source,id);return `<button type="button" class="life-picture-choice${r.neighbor===id?' selected':''}" data-life-neighbor="${id}" aria-label="${esc(s.label)}" aria-pressed="${r.neighbor===id}">${lifeStageDiagram(s,true)}<strong>${esc(s.label)}</strong>${r.neighbor===id?'<span class="life-tick" aria-hidden="true">✓</span>':''}</button>`;}).join('')}</div>${button(`data-life-neighbor="unsure" aria-pressed="${r.neighbor==='unsure'}"`,'Not sure yet',r.neighbor==='unsure')}</section></div>${button('data-life-page="meaning"','Next: read our forward link',true)}`;}
function meaning(r){return `<h2 id="life-prompt" tabindex="-1">Read our proposed forward link</h2><p class="life-chart-question"><strong>Chart question:</strong> ${esc(r.source.question)}</p>${hearButton('What would the correct forward link mean? '+r.source.question+' Choose same individual growing or changing, offspring in another generation, or not sure yet.','Hear this link question')}${proposed(r.source,{neighbor:r.neighbor})}<fieldset class="life-meaning"><legend>What would the correct forward link mean?</legend><div class="life-meaning-choices" role="group" aria-label="Meaning of the correct forward link">${lifeMeanings.map(x=>button(`data-life-meaning="${x.id}" aria-pressed="${r.meaning===x.id}"`,`${x.label}${r.meaning===x.id?' · selected':''}`,r.meaning===x.id)).join('')}</div></fieldset>${button('data-life-check','Check / keep this trail',true)}<p class="tiny">Blank and uncertain choices can be kept. Latest 8 trails stay in this visit; keeping a ninth removes the oldest.</p>${button('data-life-page="connect"','Change our stage choice')}`;}

function record(r,c,index){return `<section class="life-record" tabindex="-1"><h3>${index===r.checks.length-1&&lifeCheckMatches(r,c)?'Latest kept trail for these choices':'Earlier recorded trail'}</h3><p><strong>Recorded question:</strong> ${esc(c.source.question)}</p><p><strong>Chosen neighbor:</strong> ${esc(stageLabel(c.source,c.input.neighbor))}.<br><strong>Chosen meaning:</strong> ${esc(meaningLabel(c.input.meaning))}.</p><p><strong>Recorded neighbor outcome:</strong> ${recordedMatch(c.neighborMatch)}.<br><strong>Recorded meaning outcome:</strong> ${recordedMatch(c.meaningMatch)}.</p><p class="life-feedback">${esc(c.feedback)}</p><details><summary>Proposed pair kept with this check</summary>${proposed(c.source,c.input)}</details><p class="tiny">Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}. Supplied facts and a no-extra-help record do not establish independent reading or biological discovery.</p>${fullSource(c.source)}</section>`;}
function kept(r){return `<h2 id="life-prompt" tabindex="-1">Our revisable life-stage trail</h2>${r.checks.length?record(r,r.checks.at(-1),r.checks.length-1):'<p>No trail has been kept yet. Your picture choices stay available.</p>'}${button('data-life-page="connect"','Change our trail',true)} ${button('data-life-page="inspect"','Inspect the stages')}${r.checks.length>1?`<details><summary>Earlier kept trails (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>record(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="life-catalog"><h2>Choose a chart question</h2><p>Eight questions share this named-species chart. All questions are open.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="life-start-form"><label for="life-case">Chart question</label><select name="case" id="life-case">${lifeCases.map(s=>`<option value="${s.id}"${v.current?.source.id===s.id?' selected':''}>${esc(s.question)}</option>`).join('')}</select><button class="secondary" type="submit">Start this question</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our chart visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-life-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function lifeStagesPage(state){const v=lifeView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#living">← Living Garden</a><h1>One butterfly, changing bodies</h1><p>The wildlife corner needs a picture-story label. Connect stages on our small-white butterfly chart.</p></header>`;if(v.status==='unavailable')return `<div class="life-page">${heading}<section class="life-sheet"><h2>Earlier work is safe</h2><p>This saved chart work uses a format we cannot continue here. It stays unchanged; the garden remains open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.lifeStages,null,2))}</pre></details></section></div>`;return `<div class="life-page">${heading}<section class="life-sheet">${r?`<nav class="life-tabs" aria-label="Life-stage pages">${lifePages.map(p=>button(`data-life-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({inspect:'Inspect',connect:'Stage',meaning:'Meaning',kept:'Kept trail'})[p],v.page===p)).join('')}</nav>`: ''}${r?`<p class="life-task-title"><strong>${esc(r.source.commonName)}</strong>${r.familiar?' · Familiar chart; this question may differ':''}</p>`:''}<p id="life-status" role="status" tabindex="-1" class="life-status"></p>${r?v.page==='connect'?connect(r):v.page==='meaning'?meaning(r):v.page==='kept'?kept(r):inspect(r):`<h2 id="life-prompt" tabindex="-1">Open a life-stage picture story</h2><p>A caterpillar, chrysalis and adult can be the same individual. A female’s eggs begin offspring, another generation.</p>${catalog(v)}`}${r?`<details id="life-facts" data-round="${r.id}"><summary>Our four-stage picture story and facts</summary><p>${esc(r.source.overview)}</p><p>One named example: ${esc(r.source.commonName)}, <i>${esc(r.source.species)}</i>. These facts are supplied; they are not a rule about every butterfly’s food or timing.</p>${fullSource(r.source)}${hearButton(r.source.overview,'Hear the overview')}</details><details id="life-help" data-round="${r.id}"><summary>Help us connect the chart</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear this help')}${button('data-life-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another chart question</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function lifeStagesNotes(state){const v=lifeView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Life stages · earlier format</summary><pre>${esc(JSON.stringify(state.lifeStages,null,2))}</pre></details>`;return `<details class="panel life-page"><summary>Living Garden life stages (${v.rounds.length} chart visits)</summary><p>Original teaching pictures and supplied facts about a possible small-white life story. Chart-neighbour and meaning outcomes remain separate; familiarity is shared chart familiarity across all eight tasks, not question mastery. View changes do not establish inspection or understanding. The existing host connection panel may still display and register incoming numerical facts on Living Garden routes. No independent reading, retelling, field observation or learning gain is inferred.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Familiar chart as recorded: ${r.familiar?'yes':'no'}. Support: ${esc(r.support.join(', ')||'none recorded')}. Current draft: ${esc(stageLabel(r.source,r.neighbor))}; ${esc(meaningLabel(r.meaning))}.</p>${fullSource(r.source)}${r.checks.map((c,i)=>record(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindLifeStages(state,{save,render,focus}){
 const boundId=lifeView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&lifeView(state).current?.id===boundId;
 const show=(message='',target='#life-prompt')=>{const id=lifeView(state).current?.id,open=[...document.querySelectorAll('.life-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(lifeView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#life-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 document.querySelector('#life-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||lifeView(state).current?.id!==boundId)return;const r=startLife(state,new FormData(form).get('case'));show(r?'A chart visit is ready. Earlier trails stay in their own visits.':'A new visit cannot be created because its saved visit numbers have reached the supported limit. Earlier visits remain available.',r?'#life-prompt':'#life-status');});
 document.querySelectorAll('[data-life-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||lifeView(state).current?.id!==boundId)return;const ok=resumeLife(state,Number(b.dataset.lifeResume));show(ok?'Earlier chart visit opened with its own facts and records.':'That chart visit could not be opened.');}));
 bind('[data-life-page]',b=>{setLifePage(state,b.dataset.lifePage);show();});
 bind('[data-life-view]',b=>{setLifeView(state,b.dataset.lifeView);show('Inspection picture changed; answer choices are unchanged.',`[data-life-view="${b.dataset.lifeView}"]`);});
 bind('[data-life-neighbor]',b=>{chooseLifeNeighbor(state,b.dataset.lifeNeighbor);show('Proposed neighbor changed. The meaning choice stays available.',`[data-life-neighbor="${b.dataset.lifeNeighbor}"]`);});
 bind('[data-life-meaning]',b=>{chooseLifeMeaning(state,b.dataset.lifeMeaning);show('Meaning choice updated. Earlier records stay unchanged.',`[data-life-meaning="${b.dataset.lifeMeaning}"]`);});
 bind('[data-life-check]',()=>{const c=checkLife(state);if(c)setLifePage(state,'kept');show(c?'This trail is kept with separate neighbor and meaning outcomes.':'This trail could not be kept.',c?'.life-record':'#life-status');});
 bind('[data-life-together]',()=>{addLifeSupport(state,'together');show('Thinking together recorded as support.','[data-life-together]');});
 const help=document.querySelector('#life-help');help?.addEventListener('toggle',()=>{if(help.open&&sameVisit(help)&&Number(help.dataset.round)===boundId){addLifeSupport(state,'help');save();}});
 document.querySelectorAll('.life-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b)){addLifeSupport(state,'audio');save();}}));
}
